import sys

def solve() -> None:
    # Read input
    a, b, s = map(int, sys.stdin.readline().split())

    # Calculate Manhattan distance
    distance = abs(a) + abs(b)

    # Check if it's possible to reach in exactly s steps
    if s < distance:
        print("No")
    elif (s - distance) % 2 == 0:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
"}

