# Calculate parity of the permutation by counting inversions
inversions = 0
for i in range(n):
    for j in range(i + 1, n):
        if perm[i] > perm[j]:
            inversions += 1

# Determine parity
parity = inversions % 2

# Petr's parity: 3n swaps, which has parity 3n % 2
# Alex's parity: 7n+1 swaps, which has parity (7n+1) % 2

if parity == (3 * n) % 2:
    print("Petr")
else:
    print("Um_nik")
"}

