import sys

def solve_case(s):
    stack = []
    for ch in s:
        if not stack:
            stack.append(ch)
            continue

        # Check if we can form a valid substring with the previous character
        if stack[-1] == 'B' and ch == 'B':
            # Can form "BB"
            stack.pop()
        elif stack[-1] == 'A' and ch == 'B':
            # Can form "AB"
            stack.pop()
        else:
            stack.append(ch)

    return len(stack)

def main():
    t = int(sys.stdin.readline())
    for _ in range(t):
        s = sys.stdin.readline().strip()
        print(solve_case(s))

if __name__ == "__main__":
    main()
"}

