# Parse the grid
grid = [input().strip() for _ in range(n)]

# Process each spider
spiders = []
for i in range(n):
    for j in range(m):
        if grid[i][j] != '.':
            dir = grid[i][j]
            spiders.append((i, j, dir))

# Calculate for each starting position
result = []
for start_col in range(m):
    seen = 0
    for t in range(n):  # time t = 0, 1, ..., n-1
        row = t
        col = start_col

        # Check if Om Nom is at (t, start_col) and sees any spiders
        for (r, c, d) in spiders:
            # Spider at (r, c) moving direction d
            if d == 'R':
                # At time t, spider at (r, c + t)
                if r == t and c + t == col:
                    seen += 1
            elif d == 'L':
                # At time t, spider at (r, c - t)
                if r == t and c - t == col:
                    seen += 1
            elif d == 'U':
                # At time t, spider at (r - t, c)
                if r - t == t and c == col:
                    seen += 1
            elif d == 'D':
                # At time t, spider at (r + t, c)
                if r + t == t and c == col:
                    seen += 1
    result.append(str(seen))

print(' '.join(result))
"}

