import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    points = []
    points_set = set()
    for _ in range(n):
        x = int(next(it))
        y = int(next(it))
        points.append((x, y))
        points_set.add((x, y))
    ans = 0
    for B in points:
        Bx, By = B
        for A in points:
            if A == B:
                continue
            Cx = 2 * Bx - A[0]
            Cy = 2 * By - A[1]
            if (Cx, Cy) in points_set:
                ans += 1
    ans //= 2
    print(ans)

if __name__ == '__main__':
    solve()
"}

