import math

t = int(input())
for _ in range(t):
    n, k = map(int, input().split())

    if k >= n:
        print(1)
        continue

    max_div = 1
    # Check divisors up to sqrt(n)
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            # i is a divisor
            if i <= k:
                max_div = max(max_div, i)
            # n//i is another divisor
            other = n // i
            if other <= k:
                max_div = max(max_div, other)

    print(n // max_div)
