import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    positives = []
    negatives = []
    for x in a:
        if x > 0:
            positives.append(x)
        elif x < 0:
            negatives.append(x)

    total_pos = sum(positives)
    if total_pos % 2 == 1:
        print(total_pos)
        return

    # Need to make it odd
    min_odd_pos = None
    for x in positives:
        if x % 2 == 1:
            if min_odd_pos is None or x < min_odd_pos:
                min_odd_pos = x

    max_odd_neg = None
    for x in negatives:
        if x % 2 == 1:
            if max_odd_neg is None or x > max_odd_neg:
                max_odd_neg = x

    candidates = []
    if min_odd_pos is not None:
        candidates.append(total_pos - min_odd_pos)
    if max_odd_neg is not None:
        candidates.append(total_pos + max_odd_neg)

    ans = max(candidates)
    print(ans)

if __name__ == "__main__":
    solve()
"}

