start = input().strip()
end = input().strip()
k = int(input())

MOD = 1000000007
n = len(start)

# dp[k][word] = number of ways to get to word in exactly k operations
dp = [{} for _ in range(k + 1)]
dp[0][start] = 1

for steps in range(1, k + 1):
    for word, count in dp[steps - 1].items():
        for i in range(1, n):
            new_word = word[i:] + word[:i]
            dp[steps][new_word] = (dp[steps].get(new_word, 0) + count) % MOD

print(dp[k].get(end, 0))
"}

