def can_reach(x, k):
    """Check if branch k can be reached by grasshopper at branch x"""
    if k % x == 0 and k // x >= 2:
        return True
    return False


def solve(p, y):
    """Find the highest suitable branch"""
    for k in range(y, p, -1):
        if not any(can_reach(x, k) for x in range(2, p+1)):
