def solve():
    N, M = map(int, input().split())
    i, j = map(int, input().split())

    # Create a 2D array for expected steps, indexed 1-indexed
    E = [[0.0 for _ in range(M + 1)] for _ in range(N + 1)]

    # For the bottom row, expected steps are 0
    for col in range(1, M + 1):
        E[N][col] = 0.0

    # For row N-1, we need to solve the system
    for col in range(1, M + 1):
        if col == 1:
            # Leftmost column
            E[N-1][col] = (4 + E[N-1][col+1] + E[N][col]) / 3
        elif col == M:
            # Rightmost column
            E[N-1][col] = (4 + E[N-1][col-1] + E[N][col]) / 3
        else:
            # Middle columns
            E[N-1][col] = (4 + E[N-1][col-1] + E[N-1][col+1] + E[N][col]) / 3

    # For rows above N-1, we need to solve more complex equations
    for row in range(N-2, 0, -1):
        for col in range(1, M + 1):
            if row == N:
                continue

            k = 4
            if col == 1:
                k = 3
            elif col == M:
                k = 3

            if col == 1:
                # Leftmost column
                E[row][col] = (k + E[row][col+1] + E[row+1][col]) / (k - 1)
            elif col == M:
                # Rightmost column
