    excess = []
    deficit = []

    for i, volume in enumerate(cups, 1):
        diff = volume - base_volume
        if diff > 0:
            excess.append((i, diff))
        elif diff < 0:
            deficit.append((i, -diff))

    # Check if exactly one cup gave and one cup took
    if len(excess) == 1 and len(deficit) == 1:
        # The giving cup should be the one that had more than base but now has less than base
        # The receiving cup should be the one that had less than base but now has more than base

        # Find giving cup
        giving_cup = None
        for i, vol in enumerate(cups, 1):
            if vol > base_volume and any(cup > base_volume for cup in cups):
                giving_cup = i
                break

        # Find receiving cup
        receiving_cup = None
        for i, vol in enumerate(cups, 1):
            if vol < base_volume:
                receiving_cup = i
                break

        # Check if we found both
        if giving_cup is not None and receiving_cup is not None:
