            adj[u].append(v)
            adj[v].append(u)

        # Find components after removing a
        visited_a = [False] * (n + 1)
        components_a = []

        def dfs_remove_a(start):
            stack = [start]
            visited_a[start] = True
            comp = [start]
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if v == a:
                        continue
                    if not visited_a[v]:
                        visited_a[v] = True
                        comp.append(v)
                        stack.append(v)
            return comp

        # Find all nodes not a
        nodes = [i for i in range(1, n + 1) if i != a]
        for node in nodes:
            if not visited_a[node]:
                comp = dfs_remove_a(node)
                components_a.append(comp)

        # Find components after removing b
        visited_b = [False] * (n + 1)
        components_b = []

        def dfs_remove_b(start):
