        for node in nodes:
            if not visited_b[node]:
                comp = dfs_remove_b(node)
                components_b.append(comp)

        # Count pairs that satisfy both conditions
        count = 0

        # Map nodes to component indices for each case
        node_to_idx_a = {}
        for i, comp in enumerate(components_a):
            for node in comp:
                node_to_idx_a[node] = i

        node_to_idx_b = {}
        for i, comp in enumerate(components_b):
            for node in comp:
                node_to_idx_b[node] = i

        # Count valid pairs
