for node in range(1, n + 1):
    # Find the immediate neighbor
    for neighbor in adj[node]:
        if len(adj[neighbor]) == 2:
            immediate_neighbors[node] = neighbor
            break

# Build the circle
start = 1
order = [start]
current = start
next_neighbor = immediate_neighbors[current]

while len(order) < n:
    order.append(next_neighbor)
    # Find the next immediate neighbor (not the previous one)
    for neighbor in adj[next_neighbor]:
        if neighbor != order[-2]:
            next_neighbor = neighbor
            break

