    flights_in = {}  # from city i on day d
    flights_out = {}  # from city 0 on day d

    for _ in range(m):
        d = int(data[idx]); idx += 1
        f = int(data[idx]); idx += 1
        t = int(data[idx]); idx += 1
        c = int(data[idx]); idx += 1

        if t == 0:
            # Flight into Metropolis (city i to city 0)
            if f not in flights_in:
                flights_in[f] = {}
            flights_in[f][d] = c
        else:
            # Flight out of Metropolis (city 0 to city i)
            if d not in flights_out:
                flights_out[d] = {}
            flights_out[d][t] = c

    # For each jury member in city i, we need:
    # - To arrive in Metropolis
    # - Stay for k days
    # - Leave Metropolis

