        departure_costs = []
        for d in flights_out:
            departure_costs.append((d, flights_out[d][city]))

        # For each possible arrival day
        min_cost_for_city = float('inf')

        for arrival_day, arrival_cost in arrival_costs:
            # They need to be in Metropolis from day arrival_day to arrival_day + k - 1
            # So they need to leave on day >= arrival_day + k

