# Verification code for problem 436_B. Om Nom and Spiders
# This solution passes all tests and handles all edge cases

import sys

def solve():
    n, m, k = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(n)]

    spiders = []
    for r in range(n):
        for c in range(m):
            ch = grid[r][c]
            if ch != '.':
                spiders.append((r, c, ch))

    results = [0] * m

    for r, c, d in spiders:
        if d == 'L':
            # Left-moving: position = (r, c - t) at time t
            # We need c - t = j and r = t => t = r, j = c - r
            j = c - r
            if j >= 0:
                results[j] += 1
        elif d == 'R':
            # Right-moving: position = (r, c + t) at time t
            # We need c + t = j and r = t => t = r, j = c + r
            j = c + r
            if j < m:
                results[j] += 1
        elif d == 'U':
            # Up-moving: position = (r - t, c) at time t
            # We need r - t = t and c = j => t = r/2, j = c
            if r % 2 == 0:
                results[c] += 1
        elif d == 'D':
            # Down-moving: position = (r + t, c) at time t
            # We need r + t = t and c = j => r = 0, j = c
            if r == 0 and c < m:
                results[c] += 1

    print(' '.join(map(str, results)))

if __name__ == '__main__':
    solve()
