import heapq
from collections import defaultdict

def dijkstra(graph, source, n):
    dist = [float('inf')] * (n + 1)
    dist[source] = 0
    pq = [(0, source)]

    while pq:
        cost, city = heapq.heappop(pq)

        if cost > dist[city]:
            continue

        for day, neighbor, flight_cost in graph[city]:
            if dist[neighbor] > dist[city] + flight_cost:
                dist[neighbor] = dist[city] + flight_cost
                heapq.heappush(pq, (dist[neighbor], neighbor))

    return dist

def solve():
    import sys
    input = sys.stdin.read().split()

    idx = 0
    n = int(input[idx]); idx += 1
    m = int(input[idx]); idx += 1
    k = int(input[idx]); idx += 1

    graph_arrival = defaultdict(list)  # From cities to Metropolis
    graph_departure = defaultdict(list)  # From Metropolis to cities

    for _ in range(m):
        d = int(input[idx]); idx += 1
        f = int(input[idx]); idx += 1
        t = int(input[idx]); idx += 1
        c = int(input[idx]); idx += 1

        if f == 0:
            # Flight from Metropolis (city 0) to city t on day d
            graph_departure[0].append((d, t, c))
        else:
