from collections import defaultdict

def dijkstra(graph, source, n):
    dist = [float('inf')] * (n + 1)
    dist[source] = 0
    pq = [(0, source)]

    while pq:
        cost, city = heapq.heappop(pq)

        if cost > dist[city]:
            continue

        for day, neighbor, flight_cost in graph[city]:
            if dist[neighbor] > dist[city] + flight_cost:
                dist[neighbor] = dist[city] + flight_cost
                heapq.heappush(pq, (dist[neighbor], neighbor))

    return dist

