        components = components.strip().split(',')
        components = [c.strip() for c in components]

        # Parse components: "desolator 1" => ("desolator", 1)
        composite_components = {}
        for c in components:
            if ' ' in c:
                art_name, count = c.split()
                composite_components[art_name] = int(count)
            else:
                # This should not happen according to the problem description
                composite_components[c] = 1

        composite_artifacts[name] = composite_components

    # Initialize ally inventories
    inventories = {i: {} for i in range(1, k+1)}

    # Process purchases
    for _ in range(q):
        parts = input().split()
        if not parts:
            continue
        ally_id = int(parts[0])
        artifact_name = ' '.join(parts[1:])

        # Add to inventory
        if artifact_name in inventories[ally_id]:
            inventories[ally_id][artifact_name] += 1
        else:
            inventories[ally_id][artifact_name] = 1

        # Check if we can create any composite artifact
        # We need to check all composite artifacts
        found = False
        for composite_name, required in composite_artifacts.items():
            # Check if we have all required components
            can_create = True
            for comp_name, comp_count in required.items():
                if inventories[ally_id].get(comp_name, 0) < comp_count:
                    can_create = False
                    break

            if can_create:
                # Create the composite artifact
                inventories[ally_id][composite_name] = 1
                # Remove all required components
                for comp_name, comp_count in required.items():
                    inventories[ally_id][comp_name] -= comp_count
                    if inventories[ally_id][comp_name] == 0:
                        del inventories[ally_id][comp_name]

                found = True
                break  # Only one composite artifact can be created per purchase

        # If no composite artifact was created, continue
        if not found:
            continue

    # Output results
    for i in range(1, k+1):
        inventory = inventories[i]
        if not inventory:
            print(0)
            continue

        print(len(inventory))
        # Sort by lexicographical order
        for name in sorted(inventory.keys()):
            print(f"{name} {inventory[name]}")

# Run the solution
