import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    grid = []
    idx = 2

    for i in range(n):
        row = data[idx:idx+m]
        grid.append(row)
        idx += m

    # Find all connected components of empty cells
    visited = [[False]*m for _ in range(n)]
    components = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # BFS to find the entire component
                from collections import deque
                q = deque([(i, j)])
                visited[i][j] = True
                component = [(i, j)]

                while q:
                    x, y = q.popleft()
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
