def solve():
    MOD = 1000000007
    start = input().strip()
    end = input().strip()
    k = int(input().strip())

    n = len(start)

    # Check if anagrams
    if sorted(start) != sorted(end):
        print(0)
        return

    # Find all valid shift amounts s (mod n) that map start to end
    valid_shifts = []
    for s in range(n):
        valid = True
        for i in range(n):
            if start[i] != end[(i + n - s) % n]:
                valid = False
                break
        if valid:
            valid_shifts.append(s)

    # If no valid shift, answer is 0
    if not valid_shifts:
        print(0)
        return

    # DP: dp[i][j] = number of sequences of i operations that result in sum ≡ j mod n
    # We only need the last row
    dp = [0] * n
    dp[0] = 1  # after 0 operations, sum = 0

    for _ in range(k):
        new_dp = [0] * n
        for j in range(n):
            if dp[j] == 0:
                continue
            for r in range(1, n):
                new_dp[(j + r) % n] = (new_dp[(j + r) % n] + dp[j]) % MOD
        dp = new_dp

    ans = sum(dp[s] for s in valid_shifts) % MOD
    print(ans)

solve()
