def solve():
    # Read input
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return

    N, M = int(data[0]), int(data[1])
    i, j = int(data[2]), int(data[3])

    # If already on bottom row
    if i == N:
        print("0.0000000000")
        return

    # Create expected values table
    E = [[0.0 for _ in range(M + 1)] for _ in range(N + 1)]

    # Bottom row (row N) has expected value 0
    for col in range(1, M + 1):
        E[N][col] = 0.0

    # Row N-1
    for col in range(1, M + 1):
        if 1 < col < M:
            # Can move left, right, down
            E[N-1][col] = 1.0 + (E[N][col-1] + E[N][col+1] + E[N][col]) / 3.0
        else:
            # For leftmost column (col == 1)
            if col == 1:
                E[N-1][col] = 1.0 + (E[N][col+1] + E[N][col]) / 2.0
            # For rightmost column (col == M)
            else:
                E[N-1][col] = 1.0 + (E[N][col-1] + E[N][col]) / 2.0

    # Solve for rows N-2 down to 1
    for row in range(N-2, 0, -1):
        for col in range(1, M + 1):
            if 1 < col < M:
                E[row][col] = 1.0 + (E[row][col-1] + E[row][col+1] + E[row+1][col]) / 3.0
            elif col == 1:
                E[row][col] = 1.0 + (E[row][col+1] + E[row+1][col]) / 2.0
            else:  # col == M
                E[row][col] = 1.0 + (E[row][col-1] + E[row+1][col]) / 2.0

