    max_height = max(a)

    for i in range(n):
        for row in range(1, a[i] + 1):
            edges[i].append(row)

    # Maximum bipartite matching
    def bpm(u, seen, match_to):
        for v in edges[u]:
            if v not in seen:
                seen.add(v)
                if match_to[v] == -1 or bpm(match_to[v], seen, match_to):
                    match_to[v] = u
                    return True
        return False

    match_to = [-1] * (max_height + 1)
    result = 0

    for u in range(n):
        seen = set()
        if bpm(u, seen, match_to):
            result += 1

    print(result)

