t = int(input())
for _ in range(t):
    n, m = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))

    # Group by b value
    b1_apps = []
    b2_apps = []
    for mem, con in zip(a, b):
        if con == 1:
            b1_apps.append(mem)
        else:
            b2_apps.append(mem)

    # Sort by memory descending
    b1_apps.sort(reverse=True)
    b2_apps.sort(reverse=True)

    # Try all possible combinations
    min_conv = float('inf')

    # Try all possible b1 apps
    for i in range(len(b1_apps) + 1):
        # Take first i b1 apps
        total = sum(b1_apps[:i])
        conv = i

        if total >= m:
            min_conv = min(min_conv, conv)
        else:
            # Need some b2 apps
            needed = m - total
            for j in range(len(b2_apps) + 1):
                if j <= len(b2_apps) and sum(b2_apps[:j]) >= needed:
                    min_conv = min(min_conv, i + j)
                    break

    if min_conv != float('inf'):
        print(min_conv)
    else:
        print(-1)
"}

