import sys
import math

def is_power_of_two(x):
    return (x > 0) and (x & (x - 1)) == 0

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    xs = list(map(int, data[1:1+n]))

    # Sort the points
    xs.sort()

    max_size = 0
    best_subset = []

    # Try each point as a potential first element
    for i in range(n):
        # Try to find the longest valid chain starting from xs[i]
        # We'll use a breadth-first search approach

        # For each point, we'll track which points are powers of two away
        pow2_points = {}
        for j in range(n):
            diff = abs(xs[i] - xs[j])
            if is_power_of_two(diff):
                pow2_points[j] = diff

        # Now try to build chains
        visited = set([i])
        current_set = [xs[i]]

        # Use a queue for BFS
        queue = [i]

        while queue:
            start_idx = queue.pop(0)

            # Find all points that are powers of two away from xs[start_idx]
            for end_idx in pow2_points:
                if end_idx not in visited:
                    visited.add(end_idx)
                    current_set.append(xs[end_idx])
                    queue.append(end_idx)

        # Now check if all pairwise distances in current_set are powers of two
        valid = True
        for a in range(len(current_set)):
            for b in range(a+1, len(current_set)):
                if not is_power_of_two(abs(current_set[a] - current_set[b])):
                    valid = False
                    break
            if not valid:
                break

        if valid and len(current_set) > max_size:
            max_size = len(current_set)
            best_subset = current_set[:]

    print(max_size)
    if max_size > 0:
        print(' '.join(map(str, best_subset)))

solve()
