import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    s = data[1] if len(data) > 1 else ""

    if n == 1:
        print("YES")
        print(s)
        return

    # Try all possible substrings
    for length in range(1, n + 1):
        for start in range(n - length + 1):
            end = start + length
            substring = s[start:end]

            # Count character frequencies
            freq = {}
            max_count = 0
            for ch in substring:
                freq[ch] = freq.get(ch, 0) + 1
                if freq[ch] > max_count:
                    max_count = freq[ch]

            # Check if this substring is diverse
            # For length L: max allowed count = (L // 2) - 1 if even, else (L // 2)
            if max_count <= (length // 2) - 1 if length % 2 == 0 else (length // 2):
                print("YES")
                print(substring)
                return

    print("NO")

if __name__ == "__main__":
    solve()
"}

