import bisect

def solve():
    input = sys.stdin.read().split()
    if not input:
        return

    data = list(map(int, input))
    n = data[0]

    add_times = {}
    remove_times = {}

    idx = 1
    for _ in range(n):
        a = data[idx]
        t = data[idx+1]
        x = data[idx+2]
        idx += 3

        if a == 1:
            # Add x at time t
            if x not in add_times:
                add_times[x] = []
            bisect.insort(add_times[x], t)
        elif a == 2:
            # Remove x at time t
            if x not in remove_times:
                remove_times[x] = []
            bisect.insort(remove_times[x], t)
        elif a == 3:
            # Query: how many x at time t?
            if x not in add_times:
                add_count = 0
            else:
                add_count = bisect.bisect_right(add_times[x], t)

            if x not in remove_times:
                remove_count = 0
            else:
                remove_count = bisect.bisect_right(remove_times[x], t)

            print(add_count - remove_count)

if __name__ == "__main__":
    solve()
