import sys

def format_sequence(s):
    result = []
    i = 0
    n = len(s)

    # Process the string character by character
    while i < n:
        if s[i] == ',':
            result.append(', ')
            i += 1
        elif s[i] == '':
            # Handle sequences of spaces
            # Skip all spaces
            i += 1
            continue
        elif s[i] == '.' and i + 2 < n and s[i+1] == '.' and s[i+2] == '.':
            # Check if this is three dots followed by something
            # Add space before if needed
            if len(result) > 0 and result[-1] != ',':
                result.append('')
            # Check if we're at the beginning
            if len(result) == 0:
                # No space before at beginning
                result.append('...')
            else:
                result.append('...')
            i += 3
        else:
            # Number: read all digits
            start = i
            while i < n and s[i] in '0123456789':
                i += 1
            # Handle comma after number
            if i < n and s[i] == ',':
                result.append('')
                i += 1
            # Handle three dots after number
            elif i < n and s[i] == '.' and i + 2 < n and s[i+1] == '.' and s[i+2] == '.':
                result.append('')
                i += 3
            # Number is just the digits
            result.append(s[start:i])

    # Special case: if last token is a comma, remove the trailing space
    if len(result) > 0 and result[-1] == ',':
        result[-1] = ','

    return ''.join(result)

def main():
    s = sys.stdin.read().strip()
    print(format_sequence(s))

if __name__ == '__main__':
    main()
"}

