if k == 1:
    print(' '.join(map(str, range(1, n + 1))))
else:
    # Start with 1
    perm = [1]
    next_val = 1 + k

    # Construct the permutation
    for i in range(1, n):
        if i % 2 == 1:
            # Large difference (add k)
            next_val = perm[-1] + k
        else:
            # Small difference (subtract 1)
            next_val = perm[-1] - 1

        perm.append(next_val)

    print(' '.join(map(str, perm)))
