from collections import Counter

counts = Counter(volumes)
base_volume = counts.most_common(1)[0][0]

if counts[base_volume] == n:
    print("Exemplary pages.")
elif counts[base_volume] == n - 1:
    # There should be exactly two cups with different volumes
    different_volumes = [vol for vol in volumes if vol != base_volume]
    if len(different_volumes) == 2:
        vol1, vol2 = different_volumes

        # Check if they are symmetric around base_volume
        if (vol1 == base_volume + v and vol2 == base_volume - v) or \
           (vol1 == base_volume - v and vol2 == base_volume + v):
            v = abs(vol1 - base_volume)
            from_idx = volumes.index(vol1) + 1
            to_idx = volumes.index(vol2) + 1

            # Ensure from_idx and to_idx are different
            if from_idx != to_idx:
                print(f"{v} ml. from cup #{from_idx} to cup #{to_idx}")
            else:
                print("Unrecoverable configuration.")
        else:
            print("Unrecoverable configuration.")
    else:
        print("Unrecoverable configuration.")
else:
    print("Unrecoverable configuration.")
