def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def smallest_prime_factor(n):
    if n % 2 == 0:
        return 2
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return i
    return n  # n itself is prime

def is_prime_power(n):
    if n == 1:
        return False
    p = smallest_prime_factor(n)
    while n % p == 0:
        n //= p
    return n == 1

def solve():
    n = int(input())
    if n == 1:
        print(1)
    elif is_prime(n):
        print(n)
    else:
        p = smallest_prime_factor(n)
        if is_prime_power(n):
            print(p)
        else:
            print(1)

solve()
