from collections import deque
import sys

def is_bad(x, y, a, b):
    """Check if cell (x, y) is bad"""
    return abs(x + y) % (2 * a) == 0 or abs(x - y) % (2 * b) == 0

def solve(a, b, x1, y1, x2, y2):
    """Find minimum number of bad cells to visit from (x1, y1) to (x2, y2)"""
    # BFS
    queue = deque([(x1, y1, 0)])  # (x, y, bad_count)
    visited = {(x1, y1): 0}

    while queue:
        x, y, bad_count = queue.popleft()

        # Check if we reached the target
        if (x, y) == (x2, y2):
            return bad_count

        # Try all 4 directions
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy

            # Check if the new cell is bad
            if is_bad(nx, ny, a, b):
                new_bad_count = bad_count + 1
            else:
                new_bad_count = bad_count

            # Check if we've seen this cell with this bad count
            if (nx, ny) not in visited or visited[(nx, ny)] > new_bad_count:
                visited[(nx, ny)] = new_bad_count
                queue.append((nx, ny, new_bad_count))

    # If we can't reach the target (shouldn't happen)
    return -1

if __name__ == "__main__":
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit(0)

    a, b, x1, y1, x2, y2 = map(int, data)

    result = solve(a, b, x1, y1, x2, y2)
    print(result)
"}

