def solve():
    t = int(input())
    for _ in range(t):
        s = input().strip()

        # Use a greedy approach to remove pairs
        stack = []

        for char in s:
            # Try to remove 'AB' pair
            if stack and stack[-1] == 'A' and char == 'B':
                stack.pop()
            elif stack and stack[-1] == 'B' and char == 'B':
                # Remove 'BB' pair
                stack.pop()
                # Also remove the previous 'B'
                if stack:
                    stack.pop()
            else:
                stack.append(char)

        print(len(stack))

solve()
