def solve():
    t = int(input())
    for _ in range(t):
        s = input().strip()

        # Greedy approach with stack
        stack = []

        for char in s:
            # Try to remove 'AB' pair (current char is 'B', previous is 'A')
            if stack and stack[-1] == 'A' and char == 'B':
                stack.pop()
            # Try to remove 'BB' pair (current char is 'B', previous is 'B')
            elif stack and stack[-1] == 'B' and char == 'B':
                stack.pop()
                if stack:
                    stack.pop()
            else:
                stack.append(char)

        print(len(stack))

solve()

