import sys

def format_sequence(s):
    tokens = []
    i = 0
    n = len(s)

    # Tokenize the string
    while i < n:
        if s[i] == ',':
            tokens.append(('comma', ','))
            i += 1
        elif s[i] == ' ':  # Handle spaces
            j = i
            while j < n and s[j] == '':
                j += 1
            tokens.append(('space', s[i:j]))
            i = j
        elif s[i] == '.':
            j = i
            while j < n and s[j] == '.':
                j += 1
            if j - i == 3:
                tokens.append(('dots', '...'))
            else:
                tokens.append(('dots', s[i:j]))
            i = j
        else:  # Number
            j = i
            while j < n and s[j].isdigit():
                j += 1
            tokens.append(('num', s[i:j]))
            i = j

    # Process tokens
    result = []
    space_needed = False

    for i, (token_type, token) in enumerate(tokens):
        if token_type == 'comma':
            # Comma should be followed by exactly one space
            # But only if there's a next token
            if i + 1 < len(tokens):
                result.append(token)
                # Add space after comma
                result.append(' ')
                space_needed = False
            else:
                result.append(token)
        elif token_type == 'dots':
            # Dots should be preceded by exactly one space
            # But only if there's a previous token
            if i > 0 and not tokens[i-1][0] == 'space':
                result.append(' ')
            result.append(token)
            space_needed = False
        elif token_type == 'num':
            # If we need a space before this number (due to commas or dots)
            if space_needed:
                result.append(' ')
            result.append(token)
            space_needed = False
        elif token_type == 'space':
            # If we have consecutive spaces
            if i + 1 < len(tokens) and tokens[i+1][0] == 'space':
                # Only keep one space
                space_needed = True
                result.append(' ')
            else:
                space_needed = False

    return ''.join(result)

def main():
    s = sys.stdin.readline().strip()
    print(format_sequence(s))

if __name__ == '__main__':
    main()
