def solve() -> None:
    n = int(input())
    times = list(map(int, input().split()))

    # Let's use dynamic programming to find the minimum time
    # dp[i]: minimum time to serve customers from position i to the end
    dp = [0] * (n + 1)

    # Base case: if we're at the last customer
    if n >= 1:
        dp[n] = times[n - 1]

    # For each position i from n-2 down to 0
    for i in range(n - 2, -1, -1):
        # Option 1: serve i and i+1, then solve from i+2
        cost1 = max(times[i], times[i + 1]) + dp[i + 2]

        # Option 2: serve i and i+2, then solve from i+3
        if i + 2 < n:
            cost2 = max(times[i], times[i + 2]) + dp[i + 3]
        else:
            cost2 = float('inf')

        # Option 3: serve i+1 and i+2, then solve from i+3
        if i + 2 < n:
            cost3 = max(times[i + 1], times[i + 2]) + dp[i + 3]
        else:
            cost3 = float('inf')

        # dp[i] is the minimum of these options
        dp[i] = min(cost1, cost2, cost3)

    # Output the minimum time
    print(dp[0])

    # Now reconstruct the solution to get the order
    result = []
