import sys
import math

def distance(a, b):
    return math.sqrt((a[0] - b[0])**2 + (a[1] - b[1])**2)

def solve():
    n, m, x = map(int, sys.stdin.readline().split())

    keyboard = []
    for _ in range(n):
        row = sys.stdin.readline().strip()
        keyboard.append([(i, j, row[j]) for j in range(len(row))])

    q = int(sys.stdin.readline())
    text = sys.stdin.readline().strip()

    # Precompute positions of each character (excluding 'S')
    char_pos = {}
    for row in keyboard:
        for pos, ch in row:
            if ch != 'S':
                if ch not in char_pos:
                    char_pos[ch] = []
                char_pos[ch].append(pos)

    # Precompute positions of 'S'
    shift_pos = [pos for row in keyboard for pos, ch in row if ch == 'S']

    other_hand = 0
    for ch in text:
        if ch not in char_pos:
            print(-1)
            return

        if ch.isupper():
            # Need to check if we can type with one hand (press both keys simultaneously)
            # Find the closest Shift key
            if len(shift_pos) == 0:
                print(-1)
                return

            # Find minimum distance between any occurrence of ch and any 'S'
            min_dist = min(distance(pos, shift_pos[0]) for pos in char_pos[ch])

            # If closest Shift key is too far, we need to use other hand
            if min_dist > x:
                other_hand += 1

    print(other_hand)

if __name__ == "__main__":
    solve()
