import heapq

def dijkstra(start, n, flights):
    """Find minimum cost to reach each city from start"""
    min_cost = [float('inf')] * (n + 1)
    min_cost[start] = 0
    pq = [(0, start)]  # (cost, city)

    while pq:
        cost, city = heapq.heappop(pq)
        if cost > min_cost[city]:
            continue

        for d, f, t, c in flights:
            if f == city:
                if min_cost[t] > min_cost[city] + c:
                    min_cost[t] = min_cost[city] + c
                    heapq.heappush(pq, (min_cost[t], t))
            elif t == city:
                if min_cost[f] > min_cost[city] + c:
                    min_cost[f] = min_cost[city] + c
                    heapq.heappush(pq, (min_cost[f], f))

    return min_cost

def solve():
    data = input().strip().split()
    n = int(data[0])
    m = int(data[1])
    k = int(data[2])

    flights = []
    for _ in range(m):
        d, f, t, c = map(int, input().strip().split())
        flights.append((d, f, t, c))

    # Find minimum cost from city 0 to all other cities (return from Metropolis)
    cost_from_0 = dijkstra(0, n, flights)

    # Find minimum cost to reach city 0 from all other cities (go to Metropolis)
    # We need to reverse the graph
    rev_flights = []
    for d, f, t, c in flights:
        if f == 0:
            rev_flights.append((d, 0, f, c))  # From 0 to city
        elif t == 0:
            rev_flights.append((d, t, f, c))  # From city to 0

    # Dijkstra from each city to 0
    cost_to_0 = [0] * (n + 1)
    for i in range(1, n + 1):
        cost_to_0[i] = dijkstra(i, n, rev_flights)[0]

