        # We need to find the cheapest way to get i to 0 on some day d1
        # Then find the cheapest way to return from 0 to i on day d2 with d2 >= d1 + k
        # But how do we know the day of the flight?

        # Actually, we need to consider all flights from i to 0 and from 0 to i

        # Get the minimum cost to go from i to 0
        min_cost_to_0 = float('inf')
        min_day_to_0 = None

        # Get the minimum cost to return from 0 to i
        min_cost_from_0 = float('inf')
        min_day_from_0 = None

        for d, f, t, c in flights:
