def solve():
    n = int(stdin.readline())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for _ in range(2 * n):
        a, b = map(int, stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)

    # Find any node with degree 4 (should exist)
    start = 1
    for i in range(1, n + 1):
        if len(adj[i]) == 4:
            start = i
            break

    # Backtracking search to find the sequence
    visited = [False] * (n + 1)
    seq = []

    def dfs(node, prev, depth):
        # Base case: we've visited all nodes
        if len(seq) == n:
            # Check if we closed the loop correctly
            # We should end at the start node, not at the previous node
            if seq[0] == seq[-1] and seq[0] != seq[-2]:
                return True
            return False

        visited[node] = True
        seq.append(node)

        # Try each neighbor
        for neighbor in adj[node]:
            if neighbor == prev:
                continue

            # Check if neighbor is at distance 1 or 2 from the previous node
            is_distance_2 = False
            for n2 in adj[neighbor]:
                if n2 == prev:
                    # This is distance 2 from prev
                    is_distance_2 = True
                    break

            if is_distance_2:
                # This is the distance-2 neighbor
                if dfs(neighbor, node, depth + 1):
                    return True
            else:
                # This is the distance-1 neighbor
                if dfs(neighbor, node, depth + 1):
                    return True

        visited[node] = False
        seq.pop()
        return False

    if dfs(start, None, 0):
        print(' '.join(map(str, seq)))
    else:
        print(-1)

