{"code": "
n, l, k = map(int, input().split())
p = list(map(int, input().split()))
a = list(map(int, input().split()))

# dp[i][w][hp][bags]: probability after first i tours, having won w tours, having won hp huge prizes, and having bags total capacity from bags won
# Actually, we don't need to track i, just the count of tours won so far

# We'll use a dictionary of dictionaries
dp = {0: {0: {0: 1.0}}}  # Start: 0 tours won, 0 huge prizes, 0 bags capacity

for tour_idx, (prob, bag) in enumerate(zip(p, a), start=1):
    new_dp = {}  # new_dp[w][hp][bags] = probability

    for w in dp:
        for hp in dp[w]:
            for bags in dp[w][hp]:
                prob = dp[w][hp][bags]

                # Consider losing the tour
                new_w = w
                new_hp = hp
                new_bags = bags
                if new_w not in new_dp:
                    new_dp[new_w] = {}
                if new_hp not in new_dp[new_w]:
                    new_dp[new_w][new_hp] = {}
                if new_bags not in new_dp[new_w][new_hp]:
                    new_dp[new_w][new_hp][new_bags] = 0.0
                new_dp[new_w][new_hp][new_bags] += prob * (1 - prob / 100)

                # Consider winning the tour
                if bag == -1:
                    # Huge prize
                    new_hp_win = hp + 1
                    new_bags_win = bags
                else:
                    # Bag
                    new_hp_win = hp
                    new_bags_win = bags + bag

                if new_w + 1 not in new_dp:
                    new_dp[new_w + 1] = {}
                if new_hp_win not in new_dp[new_w + 1]:
                    new_dp[new_w + 1][new_hp_win] = {}
                if new_bags_win not in new_dp[new_w + 1][new_hp_win]:
                    new_dp[new_w + 1][new_hp_win][new_bags_win] = 0.0
                new_dp[new_w + 1][new_hp_win][new_bags_win] += prob * (prob / 100)

    dp = new_dp

# Calculate answer
answer = 0.0
for w in dp:
    if w >= l:
        for hp in dp[w]:
            for bags in dp[w][hp]:
                if hp <= bags + k:
                    answer += dp[w][hp][bags]

print(f"{answer:.12f}")
"}

