def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # dp[i][j] = minimum time to serve customers from position i to j (1-indexed)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill dp for subarrays of length 1 and 2
    for i in range(1, n + 1):
        dp[i][i] = a[i - 1]
    for i in range(1, n):
        dp[i][i + 1] = max(a[i - 1], a[i])

    # Fill dp for subarrays of length >= 3
    for length in range(3, n + 1):
        for i in range(1, n - length + 2):
            j = i + length - 1
            # Serve i and i+1 (1-indexed)
            if i + 2 <= j:
                option1 = max(a[i - 1], a[i]) + dp[i + 2][j]
            else:
                option1 = float('inf')
            # Serve i and i+2 (1-indexed)
            if i + 3 <= j:
                option2 = max(a[i - 1], a[i + 1]) + dp[i + 3][j]
            else:
                option2 = float('inf')
            # Serve i+1 and i+2 (1-indexed)
            if i <= j - 2:
                option3 = max(a[i], a[i + 1]) + dp[i][j - 2]
            else:
                option3 = float('inf')

            dp[i][j] = min(option1, option2, option3)

    # Output the minimum time
    print(dp[1][n])

solve()
