def knight_attack_count(x, y, knights):
    """Count how many knights attack cell (x, y)"""
    count = 0
    for (xk, yk) in knights:
        # Check if knight at (xk, yk) attacks (x, y)
        if (xk - x, yk - y) in [(2, 1), (2, -1), (-2, 1), (-2, -1),
                              (1, 2), (1, -2), (-1, 2), (-1, -2)]:
            count += 1
    return count

def is_valid_final_placement(final_placement, n):
    """Check if final placement has at least floor(n^2 / 10) knights"""
    return len(final_placement) >= (n * n) // 10

def simulate_placement(initial_placement):
    """Simulate the placement process"""
    knights = initial_placement
    while True:
        # Find all cells under attack by at least 4 knights
        attacked_cells = set()
        for (x, y) in knights:
            for dx, dy in [(2, 1), (2, -1), (-2, 1), (-2, -1),
                           (1, 2), (1, -2), (-1, 2), (-1, -2)]:
                attacked_cells.add((x + dx, y + dy))

        # Check which attacked cells have exactly 4 attackers
        new_knights = []
        for cell in attacked_cells:
            if knight_attack_count(cell[0], cell[1], knights) >= 4:
                new_knights.append(cell)

        # Add new knights and check if we're done
        if not new_knights:
            return knights + new_knights

        knights = knights + new_knights

