def solve():
    n, m = map(int, input().split())
    grid = [list(input().strip()) for _ in range(n)]

    # Find all empty cells
    empty_cells = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                empty_cells.append((i, j))

    # If no empty cells, output as-is
    if not empty_cells:
        for row in grid:
            print(''.join(row))
        return

    # Try to partition empty cells into regions of size 2-5
    # This is a simplified greedy approach
    # 1. Group adjacent empty cells
    # 2. If any region has size not in {2, 3, 4, 5}, output -1
    # 3. Color with different digits

    # Find connected components of empty cells
    visited = [[False for _ in range(m)] for _ in range(n)]
    components = []

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # BFS to find the component
                component = []
                queue = [(i, j)]
                visited[i][j] = True

                while queue:
                    x, y = queue.pop(0)
                    component.append((x, y))

                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if grid[nx][ny] == '.' and not visited[nx][ny]:
                                visited[nx][ny] = True
                                queue.append((nx, ny))

                components.append(component)

    # Check if any component size is invalid
    for comp in components:
        if len(comp) not in {2, 3, 4, 5}:
            print(-1)
            return

    # Color the components
    color_map = {}  # Maps (i, j) to digit
    color = 0

    for comp in components:
        # Get the component cells
        comp_cells = [(i, j) for i, j in comp]

        # Assign a color that differs from adjacent components
        while True:
            valid = True
            for (x, y) in comp_cells:
                if grid[x][y] == '#':
                    valid = False
                    break

                # Check adjacent cells
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < m:
                        if (nx, ny) in color_map and color_map[(nx, ny)] == color:
                            valid = False
                            break
                if not valid:
                    break
            if valid:
                break
            color = (color + 1) % 10

        # Assign the color
        for (x, y) in comp_cells:
            color_map[(x, y)] = color
            color = (color + 1) % 10

    # Output the result
    for i in range(n):
        row = []
        for j in range(m):
            if grid[i][j] == '#':
                row.append('#')
            else:
                row.append(str(color_map[(i, j)]))
        print(''.join(row))

