    for comp in components:
        if len(comp) not in {2, 3, 4, 5}:
            print(-1)
            return

    # Color the components
    color_map = {}  # Maps (i, j) to digit
    color = 0

    for comp in components:
        # Get the component cells
        comp_cells = [(i, j) for i, j in comp]

        # Assign a color that differs from adjacent components
        # Try to find a valid color
        valid = False
        while True:
            if color == 10:
                color = 0
            # Check if this color is valid
            valid = True
            for (x, y) in comp_cells:
                if grid[x][y] == '#':
                    valid = False
                    break

                # Check adjacent cells
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < m:
                        if (nx, ny) in color_map and color_map[(nx, ny)] == color:
                            valid = False
                            break
                if not valid:
                    break
            if valid:
                break
            color = (color + 1) % 10

        # Assign the color
        for (x, y) in comp_cells:
            color_map[(x, y)] = color
            color = (color + 1) % 10

    # Output the result
    for i in range(n):
        row = []
        for j in range(m):
