def count_ways(start, end, k):
    MOD = 1000000007
    n = len(start)

    # dp[i][j] = number of ways to reach position i after j operations
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 1

    for i in range(k):
        for j in range(n + 1):
            if dp[i][j] == 0:
                continue

            # We can split at position j (split after j-th character)
            # This creates prefix of length j and suffix of length n-j
            # After swap, the prefix becomes suffix and vice versa
            # So the boundary moves: j -> n-j
            dp[i+1][n - j] = (dp[i+1][n - j] + dp[i][j]) % MOD

    return dp[k][0]  # We want to end with the original configuration

