def count_satisfying(a, b, l, r):
    """Count numbers x in [l, r] such that ((x mod a) mod b) != ((x mod b) mod a)"""
    if a == b:
        return 0

    if a > b:
        # Swap a and b for symmetry
        return count_satisfying(b, a, l, r)

    # a < b case
    # We want x mod b >= a

    # Count numbers in [l, r] such that x mod b >= a
    def count_mod_range(s, e, mod_val, mod_range):
        """Count numbers in [s, e] where x mod mod_range >= mod_val"""
        if e < mod_val or s > mod_range - 1:
            return 0

        # First number in [s, e] that satisfies the condition
        first = max(s, mod_val)
        if first > e:
            return 0

        # Last number in [s, e] that satisfies the condition
        last = min(e, mod_range - 1)
        if last < first:
            return 0

        # The pattern repeats every mod_range numbers
        # Count full cycles and remaining
        full_cycles = (e - first + 1) // mod_range
        count = full_cycles * mod_range

        remaining = (e - first + 1) % mod_range
        count += remaining

        return count

    return count_mod_range(l, r, a, b)

def solve():
    t = int(input())

    for _ in range(t):
        a, b, q = map(int, input().split())

        results = []
        for __ in range(q):
            l, r = map(int, input().split())
            cnt = count_satisfying(a, b, l, r)
            results.append(str(cnt))

        print(' '.join(results))

solve()
