    # a < b case
    # We want x such that (x mod a) mod b != (x mod b) mod a
    # This is equivalent to x mod a != ((x mod b) % a)

    def count_mod_range(s, e):
        """Count numbers in [s, e] such that x mod a != ((x mod b) % a)"""
