def process_string(s):
    result = []
    i = 0
    n = len(s)

    # Tokenize the string
    while i < n:
        if s[i] == ',':
            # Found a comma
            result.append(',')
            i += 1

            # Skip spaces after comma
            while i < n and s[i] == '':
                i += 1

            # If next is not the end and not a number, we need a space
            if i < n and not s[i].isdigit() and s[i] != '':
                result.append(' ')

        elif s[i] == '':
            # Found a space
            i += 1

        elif s[i] == '.':
            # Check for '...'
            if i + 2 < n and s[i+1] == '.' and s[i+2] == '.':
