import sys

def solve() -> None:
    p, y = map(int, sys.stdin.readline().split())

    # We need to find the largest number in [2, y] not divisible by any from 2 to p
    # The largest number not divisible by any from 2 to p could be y if not divisible
    # by any of those numbers.

    # Let's first check if y is divisible by any from 2 to p
    is_divisible_y = False
    if y <= p:
        is_divisible_y = True
    else:
        for i in range(2, min(p, int(y**0.5) + 1) + 1):
            if y % i == 0:
                is_divisible_y = True
                break
    if not is_divisible_y:
        print(y)
        return

    # If y is divisible, we need to check y-1
    is_divisible_y_minus_1 = False
    if y-1 <= p:
        is_divisible_y_minus_1 = True
    else:
        for i in range(2, min(p, int((y-1)**0.5) + 1) + 1):
            if (y-1) % i == 0:
                is_divisible_y_minus_1 = True
                break
    if not is_divisible_y_minus_1:
        print(y-1)
        return

    # And so on... but this is still O(p) in worst case

    # Let's think about the worst-case scenario: p=10^9, y=10^9
    # We need a smarter approach

    # If y > p, we need to check divisibility by all from 2 to p
    # But we can check only up to min(p, sqrt(y))
    # And also check if y itself is <= p
    # Actually, we can stop early because we only need to check numbers from 2 to p, and we
    # need to find the largest number in [2, y] that is not divisible by any of them.

    # A better approach: iterate from y down to 2, but for each number n, we only need to
    # check divisibility by primes up to min(p, sqrt(n)), and also check if n itself <= p

    # Check from y down to 2
    for n in range(y, 1, -1):
        # If n <= p, it's divisible by itself
        if n <= p:
            continue
        # Otherwise, check up to min(p, sqrt(n)) for small factors
        is_divisible = False
        sqrt_n = int(n**0.5)
        for i in range(2, min(p, sqrt_n) + 1):
            if n % i == 0:
                is_divisible = True
                break
        if not is_divisible:
            print(n)
            return

    print(-1)

if __name__ == "__main__":
