import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    points = [(int(next(it)), int(next(it))) for _ in range(n)]
    s = set(points)
    ans = 0
    for i in range(n):
        x1, y1 = points[i]
        for j in range(i + 1, n):
            x2, y2 = points[j]
            if (x1 + x2) % 2 == 0 and (y1 + y2) % 2 == 0:
                mid = ((x1 + x2) // 2, (y1 + y2) // 2)
                if mid in s:
                    ans += 1
    print(ans)

if __name__ == "__main__":
    solve()
"}

